package com.careerpilot.scheduling;import com.careerpilot.modules.assessment.entity.*;import com.careerpilot.modules.assessment.repository.AssessmentRepository;import com.careerpilot.modules.auth.entity.*;import com.careerpilot.modules.auth.repository.UserRepository;import com.careerpilot.modules.notification.email.EmailService;import com.careerpilot.modules.scheduling.repository.ScheduledExamRescheduleHistoryRepository;import com.careerpilot.modules.scheduling.service.ExamReminderService;import com.fasterxml.jackson.databind.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.*;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.test.web.servlet.MockMvc;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.ArgumentMatchers.any;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:selfschedule;MODE=PostgreSQL;DB_CLOSE_DELAY=-1","spring.jpa.hibernate.ddl-auto=create-drop","spring.flyway.enabled=false"})@AutoConfigureMockMvc@ActiveProfiles("test")class ScheduledExamFlowIntegrationTest{static final UUID A=UUID.fromString("a0000000-0000-0000-0000-000000000001");@Autowired MockMvc mvc;@Autowired ObjectMapper json;@Autowired AssessmentRepository assessments;@Autowired UserRepository users;@Autowired PasswordEncoder encoder;@Autowired ScheduledExamRescheduleHistoryRepository history;@Autowired com.careerpilot.modules.scheduling.repository.ScheduledExamRepository scheduled;@Autowired ExamReminderService reminders;@MockitoBean EmailService email;
@BeforeEach void seed(){reset(email);when(email.sendExamScheduled(any())).thenReturn(true);when(email.sendExamRescheduled(any())).thenReturn(true);when(email.sendExamCancelled(any())).thenReturn(true);when(email.sendExamReminder(any())).thenReturn(true);if(!assessments.existsById(A)){Assessment a=new Assessment();a.setId(A);a.setTitle("Self Schedule Bank");a.setDescription("test");a.setAssessmentType(AssessmentType.TECHNICAL_MCQ);a.setDifficulty(AssessmentDifficulty.MEDIUM);a.setDurationMinutes(20);a.setTotalQuestions(10);a.setPassingPercentage(60);a.setGenerationSource("TEST");a.setActive(true);for(int i=1;i<=12;i++)q(a,i);assessments.save(a);}if(users.findByEmail("schedule-admin@example.com").isEmpty()){User u=new User();u.setFullName("Admin");u.setEmail("schedule-admin@example.com");u.setPasswordHash(encoder.encode("Password1"));u.setRole(Role.ADMIN);u.setAccountStatus(AccountStatus.ACTIVE);users.save(u);}}
@Test void lifecycleEmailsAreTriggeredAndFailureCannotRollback()throws Exception{String s=register("self-mail@example.com");JsonNode e=create(s,Instant.now().plusSeconds(1800));verify(email).sendExamScheduled(any());UUID id=UUID.fromString(e.path("id").asText());var before=scheduled.findById(id).orElseThrow();before.setReminderSentAt(Instant.now());scheduled.saveAndFlush(before);Instant next=Instant.now().plusSeconds(2400);mvc.perform(patch("/api/v1/student/scheduled-exams/{id}/reschedule",e.path("id").asText()).header("Authorization",s).contentType("application/json").content(json.writeValueAsString(Map.of("scheduledStart",next)))).andExpect(status().isOk());verify(email).sendExamRescheduled(any());assertThat(scheduled.findById(id).orElseThrow().getReminderSentAt()).isNull();when(email.sendExamCancelled(any())).thenThrow(new IllegalStateException("SMTP down"));mvc.perform(post("/api/v1/student/scheduled-exams/{id}/cancel",e.path("id").asText()).header("Authorization",s)).andExpect(status().isOk());assertThat(scheduled.findById(id).orElseThrow().getStatus().name()).isEqualTo("CANCELLED");}
@Test void reminderIsSentOnceAndCancelledExamIsSkipped()throws Exception{Instant marker=Instant.now();var existing=scheduled.findAll();existing.forEach(e->e.setReminderSentAt(marker));scheduled.saveAllAndFlush(existing);String s=register("self-reminder@example.com");JsonNode due=create(s,Instant.now().plusSeconds(1800));JsonNode cancelled=create(s,Instant.now().plusSeconds(2100));mvc.perform(post("/api/v1/student/scheduled-exams/{id}/cancel",cancelled.path("id").asText()).header("Authorization",s)).andExpect(status().isOk());clearInvocations(email);Instant now=Instant.now();assertThat(reminders.sendDueReminders(now)).isEqualTo(1);assertThat(reminders.sendDueReminders(now.plusSeconds(1))).isZero();verify(email,times(1)).sendExamReminder(any());assertThat(scheduled.findById(UUID.fromString(due.path("id").asText())).orElseThrow().getReminderSentAt()).isNotNull();}
@Test void failedReminderRemainsEligibleForLaterRetry()throws Exception{Instant marker=Instant.now();var existing=scheduled.findAll();existing.forEach(e->e.setReminderSentAt(marker));scheduled.saveAllAndFlush(existing);String s=register("self-reminder-failure@example.com");JsonNode due=create(s,Instant.now().plusSeconds(1800));clearInvocations(email);when(email.sendExamReminder(any())).thenReturn(false);Instant now=Instant.now();assertThat(reminders.sendDueReminders(now)).isZero();assertThat(scheduled.findById(UUID.fromString(due.path("id").asText())).orElseThrow().getReminderSentAt()).isNull();assertThat(reminders.sendDueReminders(now.plusSeconds(1))).isZero();verify(email,times(2)).sendExamReminder(any());}
@Test void studentOwnsScheduleAndCrossUserIsBlocked()throws Exception{String one=register("self-one@example.com"),two=register("self-two@example.com");JsonNode e=create(one,Instant.now().plusSeconds(600));var persisted=scheduled.findById(UUID.fromString(e.path("id").asText())).orElseThrow();assertThat(persisted.getOwner()).isNotNull();assertThat(persisted.getCreatedBy().getId()).isEqualTo(persisted.getOwner().getId());assertThat(persisted.getTitle()).isNotBlank();assertThat(persisted.getScheduledEnd()).isAfter(persisted.getScheduledStart());assertThat(persisted.getAttempt()).isNull();mvc.perform(get("/api/v1/student/scheduled-exams").header("Authorization",one)).andExpect(status().isOk()).andExpect(jsonPath("$[0].id").value(e.path("id").asText()));for(var request:List.of(get("/api/v1/student/scheduled-exams/{id}",e.path("id").asText()),post("/api/v1/student/scheduled-exams/{id}/cancel",e.path("id").asText()),post("/api/v1/student/scheduled-exams/{id}/start",e.path("id").asText())))mvc.perform(request.header("Authorization",two)).andExpect(status().isNotFound());}
@Test void validatesFutureAssessmentAndDisablesAdminRoutes()throws Exception{String s=register("self-invalid@example.com"),admin=login("schedule-admin@example.com");mvc.perform(post("/api/v1/student/scheduled-exams").header("Authorization",s).contentType("application/json").content(body(UUID.randomUUID(),Instant.now().plusSeconds(60)))).andExpect(status().isNotFound());mvc.perform(post("/api/v1/student/scheduled-exams").header("Authorization",s).contentType("application/json").content(body(A,Instant.now().minusSeconds(1)))).andExpect(status().isBadRequest());mvc.perform(post("/api/v1/student/scheduled-exams").header("Authorization",admin).contentType("application/json").content(body(A,Instant.now().plusSeconds(60)))).andExpect(status().isForbidden());mvc.perform(post("/api/v1/scheduled-exams").header("Authorization",admin).contentType("application/json").content("{}")).andExpect(status().isForbidden());}
@Test void reschedulesAuditsAndCancelsIdempotently()throws Exception{String s=register("self-change@example.com");JsonNode e=create(s,Instant.now().plusSeconds(600));Instant next=Instant.now().plusSeconds(1200);String changed=mvc.perform(patch("/api/v1/student/scheduled-exams/{id}/reschedule",e.path("id").asText()).header("Authorization",s).contentType("application/json").content(json.writeValueAsString(Map.of("scheduledStart",next)))).andExpect(status().isOk()).andExpect(jsonPath("$.rescheduleCount").value(1)).andReturn().getResponse().getContentAsString();JsonNode c=json.readTree(changed);assertThat(Instant.parse(c.path("scheduledEnd").asText())).isEqualTo(Instant.parse(c.path("scheduledStart").asText()).plusSeconds(1200));assertThat(history.countByScheduledExamId(UUID.fromString(e.path("id").asText()))).isEqualTo(1);mvc.perform(post("/api/v1/student/scheduled-exams/{id}/cancel",e.path("id").asText()).header("Authorization",s)).andExpect(status().isOk()).andExpect(jsonPath("$.state").value("CANCELLED"));mvc.perform(post("/api/v1/student/scheduled-exams/{id}/cancel",e.path("id").asText()).header("Authorization",s)).andExpect(status().isOk());mvc.perform(post("/api/v1/student/scheduled-exams/{id}/start",e.path("id").asText()).header("Authorization",s)).andExpect(status().isConflict());}
@Test void windowsRepeatedStartAndPracticeFlowRemainCorrect()throws Exception{String s=register("self-start@example.com");JsonNode future=create(s,Instant.now().plusSeconds(600));mvc.perform(post("/api/v1/student/scheduled-exams/{id}/start",future.path("id").asText()).header("Authorization",s)).andExpect(status().isConflict()).andExpect(jsonPath("$.message").value("EXAM_NOT_STARTED"));JsonNode active=createRaw(s,Instant.now().plusSeconds(1200));var row=scheduled.findById(UUID.fromString(active.path("id").asText())).orElseThrow();row.setScheduledStart(Instant.now().minusSeconds(60));row.setScheduledEnd(Instant.now().plusSeconds(600));scheduled.save(row);JsonNode first=start(s,active),second=start(s,active);assertThat(first.path("id").asText()).isEqualTo(second.path("id").asText());mvc.perform(patch("/api/v1/student/scheduled-exams/{id}/reschedule",active.path("id").asText()).header("Authorization",s).contentType("application/json").content(json.writeValueAsString(Map.of("scheduledStart",Instant.now().plusSeconds(600))))).andExpect(status().isConflict());mvc.perform(post("/api/v1/assessments/{id}/attempts",A).header("Authorization",s)).andExpect(status().isCreated()).andExpect(jsonPath("$.questions.length()").value(10));}
private JsonNode create(String s,Instant t)throws Exception{return createRaw(s,t);}private JsonNode createRaw(String s,Instant t)throws Exception{return json.readTree(mvc.perform(post("/api/v1/student/scheduled-exams").header("Authorization",s).contentType("application/json").content(body(A,t))).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString());}private JsonNode start(String s,JsonNode e)throws Exception{return json.readTree(mvc.perform(post("/api/v1/student/scheduled-exams/{id}/start",e.path("id").asText()).header("Authorization",s)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString());}private String body(UUID a,Instant t)throws Exception{return json.writeValueAsString(Map.of("assessmentId",a,"scheduledStart",t));}private String register(String email)throws Exception{JsonNode r=json.readTree(mvc.perform(post("/api/v1/auth/register").contentType("application/json").content(json.writeValueAsString(Map.of("fullName","Student","email",email,"password","Password1","confirmPassword","Password1")))).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString());return"Bearer "+r.path("accessToken").asText();}private String login(String email)throws Exception{JsonNode r=json.readTree(mvc.perform(post("/api/v1/auth/login").contentType("application/json").content(json.writeValueAsString(Map.of("email",email,"password","Password1")))).andExpect(status().isOk()).andReturn().getResponse().getContentAsString());return"Bearer "+r.path("accessToken").asText();}private void q(Assessment a,int i){AssessmentQuestion q=new AssessmentQuestion();q.setAssessment(a);q.setQuestionOrder(i);q.setQuestionType(QuestionType.MCQ);q.setQuestionText("Q"+i);q.setExplanation("E"+i);q.setDifficulty(AssessmentDifficulty.MEDIUM);for(String k:List.of("A","B","C","D")){AssessmentOption o=new AssessmentOption();o.setQuestion(q);o.setOptionKey(k);o.setOptionText(k);o.setCorrect(k.equals("A"));q.getOptions().add(o);}a.getQuestions().add(q);}}
